INSERT INTO public.teacher_topic_mcqs (teacher_id,topic_key,title,questions)
SELECT 'nadia-al-nuaimy','nadia-en-ch2-lec17-exam','Topic 17 — Connective Tissue and Its Cells',$json$
[
 {"question":"Why is connective tissue known as binding or supporting tissue?","choices":["It covers the body surface and lines body cavities.","It binds and supports different parts of the body.","It allows organs to expand and contract.","It performs diffusion, filtration, and absorption."],"answer_index":1},
 {"question":"What does connective tissue consist of?","choices":["Cells, fibers, and a basement membrane.","Cells, intercellular substance, and a basement membrane.","Fibers, plasma junctions, and a basement membrane.","Cells, fibers, and intercellular substance called the matrix."],"answer_index":3},
 {"question":"Which comparison between epithelial and connective tissue is correct?","choices":["Intercellular substance is almost absent in epithelium but abundant in connective tissue.","It is abundant in epithelium but almost absent in connective tissue.","Connective cells rest on a basement membrane, while epithelial cells do not.","Epithelium binds body parts, while connective tissue covers the body surface."],"answer_index":0},
 {"question":"Which description applies to connective-tissue cells?","choices":["Connected to one another, with one cell type performing one function.","Separated from one another, with one cell type performing different functions.","Separated from one another, with several cell types performing different functions.","Connected to one another, with several cell types resting on a basement membrane."],"answer_index":2},
 {"question":"Which group of features distinguishes connective tissue?","choices":["Binds body parts, cells rest on basement membrane, abundant matrix.","Binds body parts, cells do not rest on basement membrane, abundant matrix.","Binds body parts, cells do not rest on basement membrane, matrix nearly absent.","Covers body surface, cells rest on basement membrane, matrix nearly absent."],"answer_index":1},
 {"question":"What is the most common cell in connective tissue?","choices":["Macrophage.","Adipose cell.","Epithelial cell.","Fibroblast."],"answer_index":3},
 {"question":"Which description distinguishes a fibroblast?","choices":["Large, with long branched processes, spindle-shaped in side view.","Large, with short processes, amoeboid in shape.","Spherical, with a large fat droplet occupying most of the cell.","Small, with long branched processes, cuboidal in side view."],"answer_index":0},
 {"question":"Which pairing describes the fibroblast nucleus and cytoplasm?","choices":["Flattened peripheral nucleus — homogeneous cytoplasm.","Oval nucleus — cytoplasm forming a thin ring.","Oval nucleus — homogeneous cytoplasm.","Flattened peripheral nucleus — cytoplasm forming a thin ring."],"answer_index":2},
 {"question":"What is the function of fibroblasts?","choices":["Engulf foreign particles within tissue.","Form all types of connective-tissue fibers.","Store fat for energy production.","Protect the individual from heat loss."],"answer_index":1},
 {"question":"Which comparison between macrophage and fibroblast processes is correct?","choices":["Macrophage processes are long and branched; fibroblast processes are short.","Both have long branched processes.","Both have short processes.","Macrophage processes are short compared with fibroblast processes."],"answer_index":3},
 {"question":"Which group of features applies to a macrophage?","choices":["Amoeboid, short processes, and an eccentric nucleus.","Spindle-shaped, long branched processes, and an oval nucleus.","Spherical, flattened nucleus, and cytoplasm as a thin ring.","Amoeboid, long branched processes, and a central nucleus."],"answer_index":0},
 {"question":"Why is the macrophage's function defensive?","choices":["It forms all connective-tissue fibers.","It stores fat and protects against heat loss.","It engulfs foreign particles within tissue.","It binds and supports different body parts."],"answer_index":2},
 {"question":"Which description applies to an adipose cell?","choices":["Spherical, small fat droplet, homogeneous cytoplasm.","Spherical, large fat droplet occupying most of the cell, cytoplasm as a thin ring.","Spindle-shaped, large fat droplet, homogeneous cytoplasm.","Amoeboid, small fat droplet, cytoplasm as a thin ring."],"answer_index":1},
 {"question":"What are the shape and position of an adipose-cell nucleus?","choices":["Oval and central.","Spherical and peripheral.","Flattened and central.","Flattened and peripheral, or lateral."],"answer_index":3},
 {"question":"Which two functions are performed by adipose cells?","choices":["Store fat for energy and protect against heat loss.","Store fat for energy and form connective fibers.","Engulf foreign particles and protect against heat loss.","Form connective fibers and engulf foreign particles."],"answer_index":0}
]$json$::jsonb WHERE NOT EXISTS (SELECT 1 FROM public.teacher_topic_mcqs WHERE teacher_id='nadia-al-nuaimy' AND topic_key='nadia-en-ch2-lec17-exam');

INSERT INTO public.teacher_topic_mcqs (teacher_id,topic_key,title,questions)
SELECT 'nadia-al-nuaimy','nadia-en-ch2-lec18-exam','Topic 18 — Other Connective Tissue Cells',$json$
[
 {"question":"Which cell is part of embryonic connective tissue and is unspecialized with cytoplasmic processes?","choices":["Fibroblast.","Plasma cell.","Mesenchymal cell.","Mast cell."],"answer_index":2},
 {"question":"What are the shape and position of a mesenchymal-cell nucleus?","choices":["Oval and central.","Oval and eccentric.","Flattened and peripheral.","Small and eccentric."],"answer_index":0},
 {"question":"What is the function of a mesenchymal cell?","choices":["Form all connective-tissue fibers.","Form antibodies against infection.","Engulf foreign particles in tissue.","Differentiate into any type of adult connective-tissue cell."],"answer_index":3},
 {"question":"Which comparison between mesenchymal cells and fibroblasts is correct?","choices":["Mesenchymal cells form fibers; fibroblasts differentiate into any connective cell.","Mesenchymal cells differentiate into any connective cell; fibroblasts form all types of fibers.","Mesenchymal cells form antibodies; fibroblasts form all types of fibers.","Mesenchymal cells differentiate into any connective cell; fibroblasts engulf foreign particles."],"answer_index":1},
 {"question":"Which description applies to the shape and size of a plasma cell?","choices":["Spherical or oval and relatively small.","Spherical and large.","Spindle-shaped and large.","Amoeboid with short processes."],"answer_index":0},
 {"question":"What distinguishes chromatin in the plasma-cell nucleus?","choices":["Radially arranged in a central nucleus like a clock face.","Radially arranged in an eccentric nucleus, with granular cytoplasm.","Radially arranged like a clock face or cartwheel, with an eccentric nucleus.","Radially arranged like a cartwheel, with a flattened peripheral nucleus."],"answer_index":2},
 {"question":"Which pairing correctly describes plasma-cell and mast-cell cytoplasm?","choices":["Plasma: granular; mast: homogeneous.","Plasma: thin ring; mast: homogeneous.","Plasma: homogeneous; mast: thin ring.","Plasma: homogeneous; mast: granular in appearance."],"answer_index":3},
 {"question":"Which cell produces antibodies against infection?","choices":["Mast cell.","Plasma cell.","Mesenchymal cell.","Fibroblast."],"answer_index":1},
 {"question":"Which group of features applies to a mast cell?","choices":["Relatively small, spherical or oval, homogeneous cytoplasm.","Large, spherical, cytoplasm as a thin ring.","Large, spherical, granular-appearing cytoplasm.","Large, spindle-shaped, homogeneous cytoplasm."],"answer_index":2},
 {"question":"What characterizes the mast-cell nucleus?","choices":["Small and eccentric.","Oval and central.","Flattened and peripheral.","Large and central."],"answer_index":0},
 {"question":"What effect does mast-cell histamine have on smooth muscle in pulmonary bronchioles?","choices":["Prevents blood clotting.","Increases capillary permeability.","Forms antibodies against infection.","Causes smooth-muscle contraction."],"answer_index":3},
 {"question":"What effect does histamine have on blood capillaries?","choices":["Constriction to increase permeability.","Dilation to increase permeability.","Dilation to reduce permeability.","Constriction to reduce permeability."],"answer_index":1},
 {"question":"Which mast-cell substance–effect pairing is correct?","choices":["Heparin — prevents blood clotting.","Histamine — prevents blood clotting.","Heparin — contracts smooth muscle in pulmonary bronchioles.","Heparin — dilates capillaries to increase permeability."],"answer_index":0},
 {"question":"Which cell–function pairing is incorrect?","choices":["Mesenchymal cell — differentiates into any adult connective-tissue cell.","Plasma cell — forms antibodies against infection.","Mast cell — forms all connective-tissue fibers.","Macrophage — engulfs foreign particles in tissue."],"answer_index":2},
 {"question":"Which pair represents other cells found in connective tissue in addition to the six listed types?","choices":["Guard cells and reticular cells.","Companion cells and pigment cells.","Guard cells and companion cells.","Reticular cells and pigment cells."],"answer_index":3}
